// Normalize the mime_type on the downloaded document so "Route Document Types" can branch correctly.
const items = $input.all();

const calendarTypes = ['text/calendar', 'application/ics', 'text/x-calendar'];
const xmlTypes = ['application/xml', 'text/xml'];

for (const item of items) {
  let mimeType = item.json.mime_type;

  if (!mimeType) {
    mimeType = $('Get File (Document)').first().json.mime_type
      || $('Telegram Trigger1').first().json.message.document.mime_type;
  }

  if (calendarTypes.includes(mimeType)) {
    mimeType = 'mapped/calendar';
  } else if (xmlTypes.includes(mimeType)) {
    mimeType = 'mapped/xml';
  }

  item.json.mime_type = mimeType;
}

return items;

