const items = $input.all();
let outputRows = [];

for (const item of items) {
  const data = item.json;

  const stock = Number(data.total_stock ?? 0);
  const reorderLevel = Number(data.reorder_level ?? 10);
  const name = data.name ?? 'منتج بدون اسم';
  const category = data.category ?? 'غير محدد';
  const status = stock <= reorderLevel ? 'قرب يخلص ⚠️' : 'متوفر ✅';

  outputRows.push({
    json: {
      product_name: name,
      category: category,
      stock_quantity: stock,
      reorder_level: reorderLevel,
      status: status
    }
  });
}

return outputRows;

const item = $input.first().json;

// branch_id: dashboard sets it explicitly; telegram path defaults
const branch_id = item.branch_id || 'branch_1';

// basic sanitize: trim, strip control chars, cap length
let text = (item.Text || '').toString();
text = text.replace(/[\u0000-\u001F\u007F]/g, '').trim().slice(0, 4000);

return [{
  json: {
    ...item,
    Text: text,
    branch_id
  }
}];
